/// <summary>
/// Overriden funtion
/// </summary>
/// <param name = "_record">record</param>
/// <param name = "_isWriteOperation">write operation</param>
public static void DBOpInTransaction(Common _record, boolean _isWriteOperation)
{
    NDXRecordLockCompare lNDXUtilityTableRecordDiff;
    NDXRecordLockSetup lNDXRecordLockSetup;

    if(_record && _isWriteOperation && NDXRecordLockCompare::recordHasNewVersion(_record) && NDXRecordLockCompare::useRecordLockView(_record))
    {
        lNDXUtilityTableRecordDiff = new NDXRecordLockCompare(_record.TableId);
        lNDXUtilityTableRecordDiff.checkRecordForDifference(_record);
    }

    next DBOpInTransaction(_record, _isWriteOperation);

    if(_record)
    {
        lNDXRecordLockSetup = NDXRecordLockSetup::find(_record.TableId,true);
        if(lNDXRecordLockSetup && lNDXRecordLockSetup.LastRecVersion != _record.RecVersion)
        {
            ttsbegin;
            lNDXRecordLockSetup.LastRecVersion = _record.RecVersion;
            lNDXRecordLockSetup.update();
            ttscommit;
        }
    }
}
